/** Public URL if a still exists for this company + cell slug (full original). */
export function productImageUrl(companyId, slug) {
  if (!companyId || !slug) return null
  return PRODUCT_IMAGE_MANIFEST[companyId]?.[slug] || null
}

/** Matrix-sized thumb (~480px) when optimize:product-images has been run. */
export function productImageThumbUrl(companyId, slug) {
  if (!companyId || !slug) return null
  return PRODUCT_IMAGE_THUMBS[companyId]?.[slug] || null
}

/** Detail hero (~1280px) when optimize:product-images has been run. */
export function productImageMdUrl(companyId, slug) {
  if (!companyId || !slug) return null
  return PRODUCT_IMAGE_MD[companyId]?.[slug] || null
}

/** Convention path (may 404 until the file is dropped). */
export function productImageConventionPath(companyId, slug) {
  if (!companyId || !slug) return null
  return `/images/products/${companyId}/${slug}.jpg`
}

